import re, json, os, urllib.request, time

BASE = "https://web.archive.org/web/20250822092038/https://github.com/Mitradis/Windows-10-DISM-Scripts"
os.makedirs('W10_2025', exist_ok=True)

def get(url):
    req = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
    for attempt in range(3):
        try:
            with urllib.request.urlopen(req, timeout=60) as r:
                return r.read().decode('utf-8', errors='ignore')
        except Exception as e:
            print("  retry", attempt, e)
            time.sleep(3)
    return None

def extract_lines(raw):
    i = raw.find('"rawLines"')
    if i < 0: return None
    seg = raw[i:]
    j = seg.find('[')
    depth = 0
    in_str = False; esc = False
    for k in range(j, len(seg)):
        c = seg[k]
        if in_str:
            if esc: esc = False
            elif c == '\\': esc = True
            elif c == '"': in_str = False
        else:
            if c == '"': in_str = True
            elif c == '[': depth += 1
            elif c == ']':
                depth -= 1
                if depth == 0:
                    return json.loads(seg[j:k+1])
    return None

for name in ["README.md", "_readme.txt", "_Clear.ps1", "_Clear.reg", "Clear.log"]:
    url = f"{BASE}/blob/main/{name}"
    print("==", name)
    raw = get(url)
    if not raw:
        print("  FETCH FAIL"); continue
    lines = extract_lines(raw)
    if lines:
        with open(f'W10_2025/{name}','w',encoding='utf-8') as f:
            f.write('\n'.join(lines))
        print("  saved", len(lines), "lines")
    else:
        print("  no rawLines payload")
    time.sleep(1)

for tree in ["PostClear", "Replace", "Replace/Windows"]:
    url = f"{BASE}/tree/main/{tree}"
    print("== tree", tree)
    raw = get(url)
    if raw:
        items = set(re.findall(r'Mitradis/Windows-10-DISM-Scripts/(?:blob|tree)/main/([^"&?]+?)["&?]', raw))
        for it in sorted(items):
            print("  -", it)
    time.sleep(1)
EOF

